export function MessageIcon({
  name,
  size = 18
}: {
  name: keyof typeof icons
  size?: number
}): React.JSX.Element {
  const icon = icons[name]
  return (
    <svg
      className="message-icon"
      width={size}
      height={size}
      viewBox={icon.viewBox}
      fill="currentColor"
      stroke="none"
      aria-hidden="true"
      focusable="false"
    >
      {icon.paths.map((path, index) => (
        <path key={index} {...path} />
      ))}
    </svg>
  )
}
